package com.salati.app

data class FiqhEntry(val title: String, val summary: String, val source: String)

object FiqhGuide {
    val topics = listOf("أركان الوضوء", "سنن الوضوء", "نواقض الوضوء", "شروط الصلاة", "أركان الصلاة", "واجبات الصلاة", "سنن الصلاة", "مبطلات الصلاة")

    private val entries = mapOf(
        "أركان الوضوء" to mapOf(
            "الحنفي" to FiqhEntry("فرائض الوضوء", "أربعة: غسل الوجه، وغسل اليدين إلى المرفقين، ومسح ربع الرأس، وغسل الرجلين إلى الكعبين.", "الفقه على المذاهب الأربعة؛ الموسوعة الفقهية الكويتية"),
            "المالكي" to FiqhEntry("فرائض الوضوء", "المشهور سبعة: النية، وغسل الوجه، وغسل اليدين إلى المرفقين، ومسح جميع الرأس، وغسل الرجلين إلى الكعبين، والدلك، والفور (الموالاة).", "مختصر خليل وشروحه؛ الفقه على المذاهب الأربعة"),
            "الشافعي" to FiqhEntry("فرائض الوضوء", "ستة: النية، وغسل الوجه، وغسل اليدين إلى المرفقين، ومسح بعض الرأس، وغسل الرجلين إلى الكعبين، والترتيب.", "منهاج الطالبين وشروحه؛ الفقه على المذاهب الأربعة"),
            "الحنبلي" to FiqhEntry("فرائض الوضوء", "ستة في المشهور: غسل الوجه (ومن ذلك المضمضة والاستنشاق)، وغسل اليدين، ومسح الرأس كله، وغسل الرجلين، والترتيب، والموالاة. والنية شرط لصحة الوضوء.", "زاد المستقنع وشروحه؛ الفقه على المذاهب الأربعة")
        ),
        "سنن الوضوء" to madhhabEntries("سنن الوضوء", "تتضمن التسمية، والسواك، والمضمضة والاستنشاق، وغسل الكفين أولًا، والتثليث، وتقديم اليمنى؛ وتختلف درجة بعض الأعمال وعدّها بين المذاهب. راجع التفصيل في المرجع."),
        "نواقض الوضوء" to madhhabEntries("نواقض الوضوء", "من أشهر أبواب النواقض: الخارج من السبيلين، وزوال العقل، والنوم، ومس الفرج، ولمس المرأة، وخروج النجاسة من غير السبيلين. تختلف المذاهب في بعض الصور والشروط؛ لا تُعمّم حكمًا واحدًا على الجميع."),
        "شروط الصلاة" to madhhabEntries("شروط الصلاة", "من الشروط العامة: الطهارة من الحدث والنجاسة، وستر العورة، واستقبال القبلة، ودخول الوقت، والنية. تفاصيل الشروط وما يُعد شرطًا أو فرضًا تختلف في بعض المذاهب."),
        "أركان الصلاة" to madhhabEntries("أركان الصلاة", "تشمل في الجملة القيام للقادر، وتكبيرة الإحرام، وقراءة الفاتحة أو ما يقوم مقامها بحسب المذهب، والركوع، والرفع منه، والسجود، والجلوس بين السجدتين، والطمأنينة، والتشهد الأخير، والجلوس له، والسلام، والترتيب. يختلف عدّ الأركان وبعض تفاصيلها بين المذاهب."),
        "واجبات الصلاة" to madhhabEntries("واجبات الصلاة", "مصطلح الواجب له استعمال خاص عند الحنابلة والحنفية، بينما قد تُدرج المسائل نفسها تحت الفرض أو السنة المؤكدة في مذاهب أخرى. افتح شرح المذهب لمعرفة أثر الترك وسجود السهو."),
        "سنن الصلاة" to madhhabEntries("سنن الصلاة", "منها دعاء الاستفتاح، ورفع اليدين في مواضعه، والتأمين، والتسبيح في الركوع والسجود، والجلوسات والهيئات المسنونة. تختلف تفاصيلها بين المذاهب."),
        "مبطلات الصلاة" to madhhabEntries("مبطلات الصلاة", "من أشهر المبطلات: الحدث، والكلام عمدًا لغير مصلحة الصلاة، والأكل والشرب عمدًا، والعمل الكثير المتوالي، وترك ركن عمدًا. توجد تفصيلات واستثناءات تختلف بين المذاهب.")
    )

    fun get(topic: String, madhhab: String): FiqhEntry =
        entries[topic]?.get(madhhab) ?: FiqhEntry(topic, "لم يُضف التفصيل المعتمد لهذا الباب بعد. راجع مصدر المذهب قبل العمل بالحكم.", "يرجى مراجعة كتاب معتمد في المذهب")

    private fun madhhabEntries(title: String, summary: String) = listOf("الحنفي", "المالكي", "الشافعي", "الحنبلي").associateWith {
        FiqhEntry(title, summary, "الفقه على المذاهب الأربعة؛ الموسوعة الفقهية الكويتية")
    }
}
